const supabaseUrl = 'https://uuqedsvjlkeszrbwzizl.supabase.co';
const supabaseKey = 'YOUR_SUPABASE_SERVICE_ROLE_KEY';
const headers = { 'apikey': supabaseKey, 'Authorization': `Bearer ${supabaseKey}` };
const twoDaysAgo = new Date(Date.now() - 2*24*60*60*1000).toISOString().split('T')[0];
const loansResp = await fetch(`${supabaseUrl}/rest/v1/loans?status=eq.Closed&close_date=lte.${twoDaysAgo}&select=id,contact_id,close_date`, { headers });
const loans = await loansResp.json();
if (!Array.isArray(loans) || !loans.length) return [];
const logsResp = await fetch(`${supabaseUrl}/rest/v1/automation_logs?type=eq.review_request&select=loan_id`, { headers });
const logs = await logsResp.json();
const loggedIds = new Set((logs || []).map(l => l.loan_id));
const newLoans = loans.filter(l => !loggedIds.has(l.id));
if (!newLoans.length) return [];
const results = [];
for (const loan of newLoans) {
  const contactResp = await fetch(`${supabaseUrl}/rest/v1/contacts?id=eq.${loan.contact_id}&select=first_name,last_name,email`, { headers });
  const contacts = await contactResp.json();
  if (Array.isArray(contacts) && contacts.length) {
    results.push({ json: { loan_id: loan.id, close_date: loan.close_date, first_name: contacts[0].first_name, last_name: contacts[0].last_name, email: contacts[0].email } });
  }
}
return results;

